WITH lines AS (SELECT id, host, log_ts, level, latency_ms, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS k, v) SELECT CASE WHEN latency_ms >= 2351 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, SUM(latency_ms) FILTER (WHERE k = 'trace') AS trace_total_latency_ms, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN k = 'version' THEN 1 END), 0), 2) AS latency_ms_per_version, APPROX_PERCENTILE(latency_ms, 0.9) AS latency_ms_p90, COUNT(CASE WHEN level = 'INFO' THEN 1 END) AS info_count FROM lines GROUP BY CASE WHEN latency_ms >= 2351 THEN 'HIGH' ELSE 'LOW' END
